CREATE DATABASE TPC; USE TPC; CREATE TABLE DateDim (d_date_sk INT(4) NOT NULL, d_date_id CHAR(16) NOT NULL, d_date DATE, d_month_seq INT(4), d_week_seq INT(4), d_quarter_seq INT(4), d_year INT(4), d_dow INT(4), d_moy INT(4), d_dom INT(4), d_qoy INT(4), d_fy_year INT(4), d_fy_quarter_seq INT(4), d_fy_week_seq INT(4), d_day_name CHAR(9), d_quarter_name CHAR(6), d_holiday CHAR(1), d_weekend CHAR(1), d_following_holiday CHAR(1), d_first_dom INT(4), d_last_dom INT(4), d_same_day_ly INT(4), d_same_day_lq INT(4), d_current_day CHAR(1), d_current_week CHAR(1), d_current_month CHAR(1), d_current_quarter CHAR(1), d_current_year CHAR(1)); IMPORT INTO DateDim DSV "benchmark/tpcds/data/date_dim.csv" ROWS 5 DELIMITER "," HAS HEADER SKIP HEADER;
